begin;
-- Fill only missing orientations; preserve every unrelated metadata field.
-- A changed ID, coordinate or water type must be reviewed again.
with proposed as (select * from jsonb_to_recordset('[{"locationId":"eea-LV00790500002","latitude":57.0454,"longitude":23.3701,"seaBearing":18,"shoreOrientation":{"distanceMetres":69,"radiusMetres":60,"wayIds":[1157783509],"nearestSegment":1,"nearestWayId":1157783509,"shorePoint":{"latitude":57.0448108508983,"longitude":23.369751901113098},"method":"length-weighted-local-coastline-right-normal","precision":"estimated","source":"OpenStreetMap contributors","sourceUrl":"https://www.openstreetmap.org/copyright","license":"ODbL-1.0","checkedAt":"2026-10-22","reviewed":true,"estimated":true,"wayVersions":[{"id":1157783509,"version":1}],"snapshotFile":"2026-10-22-osm.json","reviewNote":"Individually reviewed local north-up geometry and directed OSM land-left/water-right topology. Water lies north-northeast at Klapkalnciems, east at Kesterciems and north at Ragaciems. Original offshore sampling offsets retained; no neighbouring beach orientation copied."}},{"locationId":"eea-LV00790500003","latitude":57.1156,"longitude":23.2359,"seaBearing":85,"shoreOrientation":{"distanceMetres":31,"radiusMetres":60,"wayIds":[1157931612],"nearestSegment":2,"nearestWayId":1157931612,"shorePoint":{"latitude":57.11558163990889,"longitude":23.235391794800822},"method":"length-weighted-local-coastline-right-normal","precision":"estimated","source":"OpenStreetMap contributors","sourceUrl":"https://www.openstreetmap.org/copyright","license":"ODbL-1.0","checkedAt":"2026-10-22","reviewed":true,"estimated":true,"wayVersions":[{"id":1157931612,"version":3}],"snapshotFile":"2026-10-22-osm.json","reviewNote":"Individually reviewed local north-up geometry and directed OSM land-left/water-right topology. Water lies north-northeast at Klapkalnciems, east at Kesterciems and north at Ragaciems. Original offshore sampling offsets retained; no neighbouring beach orientation copied."}},{"locationId":"eea-LV00790660001","latitude":57.0368,"longitude":23.4291,"seaBearing":8,"shoreOrientation":{"distanceMetres":12,"radiusMetres":60,"wayIds":[1157931601],"nearestSegment":3,"nearestWayId":1157931601,"shorePoint":{"latitude":57.03669483044683,"longitude":23.429072697674368},"method":"length-weighted-local-coastline-right-normal","precision":"estimated","source":"OpenStreetMap contributors","sourceUrl":"https://www.openstreetmap.org/copyright","license":"ODbL-1.0","checkedAt":"2026-10-22","reviewed":true,"estimated":true,"wayVersions":[{"id":1157931601,"version":1}],"snapshotFile":"2026-10-22-osm.json","reviewNote":"Individually reviewed local north-up geometry and directed OSM land-left/water-right topology. Water lies north-northeast at Klapkalnciems, east at Kesterciems and north at Ragaciems. Original offshore sampling offsets retained; no neighbouring beach orientation copied."}}]'::jsonb)
  as p("locationId" text, latitude double precision, longitude double precision, "seaBearing" double precision, "shoreOrientation" jsonb))
update public.locations l set metadata=l.metadata || jsonb_build_object('seaBearing',p."seaBearing",'shoreOrientation',p."shoreOrientation"),updated_at=now()
from proposed p where l.id=p."locationId" and l.active and l.water_type='coastal'
  and abs(l.latitude-p.latitude)<=0.00001 and abs(l.longitude-p.longitude)<=0.00001
  and (l.metadata->'seaBearing' is null or l.metadata->'seaBearing'='null'::jsonb);
commit;
